const test=require('node:test');
const assert=require('node:assert/strict');
const {series}=require('../metrics/service.cjs');
test('all escapes, sorted keys, inherited fields and trailing LF',()=>{
  const labels=Object.assign(Object.create({'bad-key':'ignore'}),{zone:'west',detail:'a\\b\\c "x" "y"\nnext\nlast'});
  const before={...labels};
  assert.equal(series('queue:depth',labels,7),'queue:depth{detail="a\\\\b\\\\c \\"x\\" \\"y\\"\\nnext\\nlast",zone="west"} 7\n');
  assert.deepEqual({...labels},before);
  assert.equal(series('counter_total',{},-0),'counter_total 0\n');
  assert.throws(()=>series('温度',{},1),TypeError);
});
test('reject invalid names and values',()=>{
  for(const name of ['9bad','ok\n','bad-name','']) assert.throws(()=>series(name,{},1),TypeError);
  for(const labels of [{'a-b':'x'},{'x\n':'x'},{x:7}]) assert.throws(()=>series('good',labels,1),TypeError);
  for(const value of [NaN,Infinity,-Infinity,'3']) assert.throws(()=>series('good',{},value),TypeError);
});

