function matches(pattern,value) {
  if(typeof value!=='string') return false;
  const match=pattern.exec(value);
  return !!match && match[0]===value;
}
exports.validate=(name,labels,value)=>{
  if(!matches(/^[A-Za-z_:][A-Za-z0-9_:]*$/,name)) throw new TypeError('invalid metric');
  for(const [key,text] of Object.entries(labels)) {
    if(!matches(/^[A-Za-z_][A-Za-z0-9_]*$/,key)||typeof text!=='string') throw new TypeError('invalid label');
  }
  if(typeof value!=='number'||!Number.isFinite(value)) throw new TypeError('invalid value');
};

